"""Local snapshot adapter for the LedgerLake transactions endpoint."""

from datetime import datetime


def parse_timestamp(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


class LedgerLake:
    def __init__(self, transactions):
        self.transactions = transactions

    def list_transactions(self, *, created_from, created_to):
        low = parse_timestamp(created_from)
        high = parse_timestamp(created_to)
        rows = [
            row for row in self.transactions
            if low <= parse_timestamp(row["posted_at"]) < high
        ]
        return sorted(rows, key=lambda row: (parse_timestamp(row["posted_at"]), row["id"]))
# LedgerLake snapshot API, revision 2025-01

The production endpoint is `GET /v1/transactions`. This repository's
`provider.LedgerLake` adapter uses a downloaded response, so development needs
neither credentials nor network access. `list_transactions` returns all matching
rows; this local adapter has no pagination or request limits.

| Argument | Meaning |
| --- | --- |
| `created_from` | Include posting instants equal to or later than this timestamp. |
| `created_to` | Include posting instants strictly earlier than this timestamp. |

Both arguments are timezone-aware ISO 8601 timestamps. The service compares
absolute instants in UTC; a timestamp's written calendar date does not determine
its bucket. Millisecond precision and numeric UTC offsets are supported.

Rows contain unique string `id`, `posted_at`, `kind` (`payment` or `refund`), and
nonnegative integer `amount_cents`. All rows in this product are final postings
in USD. Refund amounts are positive magnitudes. There are no pending statuses,
currency conversions, retries, or duplicate provider rows to account for.

Results are ordered by posting instant, then lexicographically by `id` for ties.

Example request:

```python
client.list_transactions(
    created_from="2025-02-28T00:00:00Z",
    created_to="2025-03-01T00:00:00Z",
)
```

From the bundled snapshot this returns `p-feb-last`, `r-feb-last`, and
`p-offset-feb`. `p-mar-open` is outside the response. The offset-written
`p-offset-feb` was posted at 23:45 UTC on February 28.
{
  "downloaded_at": "2025-03-02T12:00:00Z",
  "transactions": [
    {"id": "p-mar-open", "kind": "payment", "posted_at": "2025-03-01T00:00:00Z", "amount_cents": 9000},
    {"id": "p-feb-mid", "kind": "payment", "posted_at": "2025-02-10T12:00:00Z", "amount_cents": 12000},
    {"id": "p-feb-last", "kind": "payment", "posted_at": "2025-02-28T00:00:00Z", "amount_cents": 2500},
    {"id": "r-feb-last", "kind": "refund", "posted_at": "2025-02-28T17:30:00Z", "amount_cents": 400},
    {"id": "p-offset-feb", "kind": "payment", "posted_at": "2025-03-01T00:45:00+01:00", "amount_cents": 700}
  ]
}
import json
from pathlib import Path
import subprocess
import sys
import unittest


class ReconcileTests(unittest.TestCase):
    def reconcile(self, month, **kwargs):
        result = subprocess.run(
            [sys.executable, str(Path(__file__).resolve().parents[1] / "cli.py")],
            input=json.dumps({"op": "reconcile", "month": month, **kwargs}),
            text=True, capture_output=True, check=True,
        )
        self.assertEqual(result.stderr, "")
        return json.loads(result.stdout)

    def test_bundled_february_close(self):
        self.assertEqual(self.reconcile("2025-02"), {
            "month": "2025-02",
            "transaction_ids": ["p-feb-mid", "p-feb-last", "r-feb-last", "p-offset-feb"],
            "payment_total_cents": 15200,
            "refund_total_cents": 400,
            "net_total_cents": 14800,
        })

    def test_complete_calendar_months(self):
        for month, last_day, next_month in [
            ("2025-02", "28", "2025-03"),
            ("2024-02", "29", "2024-03"),
            ("2025-04", "30", "2025-05"),
            ("2025-01", "31", "2025-02"),
            ("2025-12", "31", "2026-01"),
            ("2099-12", "31", "2100-01"),
        ]:
            with self.subTest(month=month):
                # Deliberately shuffled, with two differently written equal instants.
                rows = [
                    ("next", "payment", f"{next_month}-01T00:00:00Z", 9000),
                    ("z-last", "refund", f"{month}-{last_day}T23:59:59.999Z", 40),
                    ("before", "payment", f"{month}-01T00:59:59.999+01:00", 8000),
                    ("a-last", "payment", f"{next_month}-01T00:59:59.999+01:00", 300),
                    ("first", "payment", f"{month}-01T01:00:00+01:00", 100),
                    ("last-midnight", "payment", f"{month}-{last_day}T00:00:00Z", 200),
                    ("offset-next", "payment", f"{month}-{last_day}T23:00:00-01:00", 7000),
                ]
                transactions = [
                    dict(id=id_, kind=kind, posted_at=timestamp, amount_cents=amount)
                    for id_, kind, timestamp, amount in rows
                ]
                self.assertEqual(self.reconcile(month, transactions=transactions), {
                    "month": month,
                    "transaction_ids": ["first", "last-midnight", "a-last", "z-last"],
                    "payment_total_cents": 600,
                    "refund_total_cents": 40,
                    "net_total_cents": 560,
                })

    def test_empty_override(self):
        self.assertEqual(self.reconcile("2025-02", transactions=[]), {
            "month": "2025-02", "transaction_ids": [],
            "payment_total_cents": 0, "refund_total_cents": 0, "net_total_cents": 0,
        })


if __name__ == "__main__":
    unittest.main()
import csv
import io
import json
from pathlib import Path
import subprocess
import sys
import unittest


class RefundsCsvTests(unittest.TestCase):
    def request(self, op="refunds_csv", **kwargs):
        result = subprocess.run(
            [sys.executable, str(Path(__file__).resolve().parents[1] / "cli.py")],
            input=json.dumps({"op": op, "month": "2025-02", **kwargs}),
            text=True, capture_output=True, check=True,
        )
        self.assertEqual(result.stderr, "")
        return json.loads(result.stdout)

    def test_bundled_refund(self):
        self.assertEqual(self.request(), {
            "month": "2025-02",
            "csv": "id,posted_at,amount_cents\nr-feb-last,2025-02-28T17:30:00Z,400\n",
        })

    def test_minimal_escaping(self):
        cases = [
            ("plain", "plain"),
            (" spaced ", " spaced "),
            ("", ""),
            ("a,b", '"a,b"'),
            ('a"b', '"a""b"'),
            ("a\rb", '"a\rb"'),
            ("a\nb", '"a\nb"'),
            ('a,\r\n"b', '"a,\r\n""b"'),
        ]
        for identifier, escaped in cases:
            with self.subTest(identifier=identifier):
                self.assertEqual(self.request(transactions=[{
                    "id": identifier, "kind": "refund",
                    "posted_at": "2025-02-15T13:00:00+01:00", "amount_cents": 0,
                }]), {
                    "month": "2025-02",
                    "csv": "id,posted_at,amount_cents\n"
                           + escaped + ",2025-02-15T13:00:00+01:00,0\n",
                })

    def test_reconcile_membership_and_order(self):
        rows = [
            ("next", "refund", "2025-02-28T23:00:00-01:00", 900),
            ("z-last", "refund", "2025-02-28T23:59:59.999Z", 40),
            ("before", "refund", "2025-02-01T00:59:59.999+01:00", 800),
            ("a-last", "refund", "2025-03-01T00:59:59.999+01:00", 30),
            ("first", "refund", "2025-01-31T23:00:00-01:00", 20),
            ("payment", "payment", "2025-02-15T00:00:00Z", 100),
        ]
        transactions = [dict(id=id_, kind=kind, posted_at=posted, amount_cents=amount)
                        for id_, kind, posted, amount in rows]
        response = self.request(transactions=transactions)
        self.assertEqual(response, {
            "month": "2025-02",
            "csv": "id,posted_at,amount_cents\n"
                   "first,2025-01-31T23:00:00-01:00,20\n"
                   "a-last,2025-03-01T00:59:59.999+01:00,30\n"
                   "z-last,2025-02-28T23:59:59.999Z,40\n",
        })
        exported = list(csv.DictReader(io.StringIO(response["csv"], newline="")))
        close = self.request(op="reconcile", transactions=transactions)
        refund_ids = {row["id"] for row in transactions if row["kind"] == "refund"}
        self.assertEqual([row["id"] for row in exported],
                         [id_ for id_ in close["transaction_ids"] if id_ in refund_ids])
        self.assertEqual(sum(int(row["amount_cents"]) for row in exported),
                         close["refund_total_cents"])

    def test_no_refunds(self):
        for transactions in [[], [{
            "id": "payment", "kind": "payment",
            "posted_at": "2025-02-15T00:00:00Z", "amount_cents": 100,
        }], [{
            "id": "outside", "kind": "refund",
            "posted_at": "2025-03-01T00:00:00Z", "amount_cents": 100,
        }]]:
            with self.subTest(transactions=transactions):
                self.assertEqual(self.request(transactions=transactions), {
                    "month": "2025-02", "csv": "id,posted_at,amount_cents\n",
                })


